export const EDITOR_CSS = "/* The in-page text editor's styles (editor.js). Loaded only on\n   /admin/edit, for signed-in staff. Its own colours and system font, so it\n   reads as a tool on top of any site, in light and dark. */\n\n:root[data-editor] {\n  --wd-editor-ink: #14161a;\n  --wd-editor-paper: #ffffff;\n  --wd-editor-line: #5b6470;\n  --wd-editor-mark: #0b57d0;\n  --wd-editor-changed: #8a5300;\n  --wd-editor-problem: #b3261e;\n  --wd-editor-saved: #146c2e;\n}\n/* Room for the bar, so it never covers the foot of the page. */\n:root[data-editor] body {\n  padding-bottom: 50vh;\n}\n\n/* Low specificity (:where), so a site's own positioning always wins. Lifting\n   marked text above its neighbours keeps it clickable where a link's hit\n   area is stretched over a whole card. */\n:where([data-copy]:not(meta)) {\n  position: relative;\n  z-index: 1;\n}\n[data-copy]:not(meta) {\n  outline: 1px dashed var(--wd-editor-line);\n  outline-offset: 3px;\n  cursor: text;\n}\n[data-copy]:not(meta):hover,\n[data-copy]:not(meta):focus-visible {\n  outline: 2px solid var(--wd-editor-mark);\n}\n[data-copy][contenteditable] {\n  outline: 3px solid var(--wd-editor-mark);\n  -webkit-user-modify: read-write-plaintext-only;\n}\n[data-copy][data-editor-state='changed'] {\n  outline: 2px solid var(--wd-editor-changed);\n}\n[data-copy][data-editor-state='problem'] {\n  outline: 3px solid var(--wd-editor-problem);\n}\n[data-copy][data-editor-state='editing'] {\n  outline: 3px solid var(--wd-editor-mark);\n}\n[data-copy][data-editor-state='saved'] {\n  outline: 2px solid var(--wd-editor-saved);\n}\n/* Saved but not live yet; stuck means a person has to look at it. */\n[data-copy][data-editor-state='waiting'] {\n  outline: 2px dashed var(--wd-editor-saved);\n}\n[data-copy][data-editor-state='stuck'] {\n  outline: 2px dashed var(--wd-editor-problem);\n}\n\n.wd-editor {\n  position: fixed;\n  inset: auto 0 0 0;\n  z-index: 2147483000;\n  max-height: 45vh;\n  overflow: auto;\n  box-sizing: border-box;\n  padding: 12px 16px;\n  border-top: 2px solid var(--wd-editor-ink);\n  background: var(--wd-editor-paper);\n  color: var(--wd-editor-ink);\n  font: 400 15px/1.45 system-ui, -apple-system, 'Segoe UI', sans-serif;\n  letter-spacing: 0;\n  text-transform: none;\n  text-align: left;\n}\n.wd-editor * {\n  box-sizing: border-box;\n  margin: 0;\n  font: inherit;\n  color: inherit;\n  letter-spacing: inherit;\n  text-transform: none;\n}\n.wd-editor > * + * {\n  margin-top: 8px;\n}\n.wd-editor__top {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 4px 16px;\n}\n.wd-editor__who {\n  font-weight: 600;\n}\n.wd-editor__pages {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 4px 12px;\n}\n.wd-editor a {\n  color: var(--wd-editor-mark);\n  text-decoration: underline;\n}\n.wd-editor a[aria-current='page'] {\n  color: var(--wd-editor-ink);\n  font-weight: 600;\n  text-decoration: none;\n}\n.wd-editor__hidden summary {\n  cursor: pointer;\n}\n.wd-editor__boxes {\n  display: grid;\n  gap: 4px;\n  margin-top: 6px;\n}\n.wd-editor__hidden[hidden],\n.wd-editor__list:empty {\n  display: none;\n}\n.wd-editor textarea {\n  width: 100%;\n  padding: 6px 8px;\n  border: 1px solid var(--wd-editor-line);\n  border-radius: 0;\n  background: var(--wd-editor-paper);\n  resize: vertical;\n}\n.wd-editor__list {\n  display: grid;\n  gap: 6px;\n  padding: 0;\n  list-style: none;\n}\n.wd-editor__item {\n  padding: 6px 8px;\n  border-left: 4px solid var(--wd-editor-changed);\n  overflow-wrap: anywhere;\n}\n.wd-editor__item[data-problem] {\n  border-left-color: var(--wd-editor-problem);\n}\n.wd-editor__waiting[hidden] {\n  display: none;\n}\n.wd-editor__waiting-note {\n  font-weight: 600;\n}\n.wd-editor__waiting .wd-editor__list {\n  margin-top: 4px;\n}\n.wd-editor__item[data-state='waiting'] {\n  border-left-color: var(--wd-editor-saved);\n}\n.wd-editor__item[data-state='stuck'] {\n  border-left-color: var(--wd-editor-problem);\n}\n.wd-editor__waiting[data-state='stuck'] .wd-editor__waiting-note {\n  color: var(--wd-editor-problem);\n}\n.wd-editor__old {\n  text-decoration: line-through;\n}\n.wd-editor__new {\n  font-weight: 600;\n}\n.wd-editor__problem {\n  color: var(--wd-editor-problem);\n}\n.wd-editor__choice {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-top: 4px;\n}\n.wd-editor__actions {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 16px;\n}\n.wd-editor button {\n  min-height: 36px;\n  padding: 4px 12px;\n  border: 1px solid var(--wd-editor-ink);\n  border-radius: 0;\n  background: var(--wd-editor-paper);\n  cursor: pointer;\n}\n.wd-editor__undo {\n  margin-left: 8px;\n}\n.wd-editor .wd-editor__save {\n  background: var(--wd-editor-ink);\n  color: var(--wd-editor-paper);\n  font-weight: 600;\n}\n.wd-editor button:disabled {\n  border-color: var(--wd-editor-line);\n  background: var(--wd-editor-paper);\n  color: var(--wd-editor-line);\n  cursor: not-allowed;\n}\n.wd-editor :focus-visible {\n  outline: 3px solid var(--wd-editor-mark);\n  outline-offset: 2px;\n}\n.wd-editor__status[data-kind='problem'] {\n  color: var(--wd-editor-problem);\n  font-weight: 600;\n}\n.wd-editor__status[data-kind='saved'] {\n  color: var(--wd-editor-saved);\n  font-weight: 600;\n}\n.wd-editor__sr {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  white-space: nowrap;\n}\n\n@media (prefers-color-scheme: dark) {\n  :root[data-editor] {\n    --wd-editor-ink: #f2f3f5;\n    --wd-editor-paper: #16181c;\n    --wd-editor-line: #a3acb9;\n    --wd-editor-mark: #8ab4f8;\n    --wd-editor-changed: #f2b85c;\n    --wd-editor-problem: #f6aea9;\n    --wd-editor-saved: #7fd69a;\n  }\n}\n\n.wd-editor__count {\n  font-weight: 600;\n}\n.wd-editor__count:empty {\n  display: none;\n}\n.wd-editor__count[data-over='true'] {\n  color: var(--wd-editor-problem);\n}\n.wd-editor__note {\n  font-weight: 600;\n}\n.wd-editor__note[hidden],\n.wd-editor button[hidden] {\n  display: none;\n}\n";
